def _noop(level, event, **fields):
    pass


def sync_inventory(items, log=None):
    log = log or _noop
    synced = skipped = 0
    for item in items:
        sku, qty = item.get('sku'), item.get('qty')
        if isinstance(qty, int) and not isinstance(qty, bool) and qty >= 0:
            log('DEBUG', 'item_synced', sku=sku, qty=qty)
            synced += 1
        else:
            log('WARNING', 'invalid_qty', sku=sku, qty=qty)
            skipped += 1
    log('INFO', 'sync_done', synced=synced, skipped=skipped)
    return {'synced': synced, 'skipped': skipped}


